{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "도시공원위원회 공무원 위원의 이해관계 있는 안건 결정 참여 가능 여부",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "이해관계 있는 위원은 그 결정에 참여할 수 없다. 공무원 위원이 소관업무와 직접 관련해 출석했더라도 특정 안건 의결에 이해관계가 있으면 그 안건의 결정에 참여할 수 없다.",
          "b_ids": "도시공원:제27조제3항"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "같은 상황에서 그 출석에 대한 위원 수당 지급 대상 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "위원회에 출석한 위원에게 예산의 범위에서 수당을 지급할 수 있으나, 공무원인 위원이 소관업무와 직접 관련하여 출석하는 경우에는 지급하지 않는다. 이 사안처럼 공무원 위원이 소관업무와 직접 관련해 출석했으므로 수당 지급 대상이 아니다.",
          "b_ids": "도시공원:제28조, 도시공원:제28조단서"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
